mapper.select:
SELECT cmpycd AS cmpycd, quatym AS quatym, quatno AS quatno, quatno AS qutno, deptcd AS deptcd, deptnm AS deptnm, empno AS empno, empnm AS empnm, custcd AS custcd, custnm AS custnm, paycdn AS paycdn, paycdnm AS paycdnm, endwk AS endwk, quatymd AS quatymd, quatymd AS qutdt, tel AS tel, remark AS remark, remark AS remk, keymannm AS keymannm, keymannm AS custemp, email AS email, validdate AS validdate, addtime AS addtime, updtime AS updtime, updemp AS updemp, (SELECT IFNULL(SUM(quatamt + quatvat), 0) FROM hsqt101t_tbl WHERE hsqt101t_tbl.cmpycd = hsqt100t_tbl.cmpycd AND hsqt101t_tbl.quatym = hsqt100t_tbl.quatym AND hsqt101t_tbl.quatno = hsqt100t_tbl.quatno) AS totamt FROM hsqt100t_tbl WHERE cmpycd = #{cmpycd}
AND quatym = #{quatym}
AND quatno = #{quatno}
AND deptcd = #{deptcd}
AND custnm LIKE CONCAT('%', #{custnm}, '%')
AND quatymd BETWEEN REPLACE(#{frdt}, '-', '') AND REPLACE(#{todt}, '-', '')
ORDER BY quatym DESC, quatno DESC

select a.cmpycd as cmpycd, a.quatym as quatym, a.quatno as quatno, a.quatno as qutno, a.deptcd as deptcd, a.deptnm as deptnm, a.empno as empno, a.empnm as empnm, a.custcd as custcd, a.custnm as custnm, a.quatymd as quatymd, a.quatymd as qutdt, a.validdate as validdate, a.remark as remark, a.remark as remk, a.keymannm as keymannm, a.tel as tel, b.qrowno as qrowno, b.itemcd as itemcd, b.itemnm as itemnm, b.itsize as itsize, b.itsize as spec, b.unit as unit, b.quatqty as quatqty, b.quatqty as quty, b.quatamt as quatamt, b.quatamt as uprc, b.quatamt as amtx, b.quatvat as quatvat, b.quatvat as vat, (ifnull(b.quatamt, 0) + ifnull(b.quatvat, 0)) as quatsum from hsqt100t_tbl a left join hsqt101t_tbl b on a.cmpycd = b.cmpycd and a.quatym = b.quatym and a.quatno = b.quatno where a.cmpycd = #{cmpycd}
and a.deptcd = #{deptcd}
and a.custnm like concat('%', #{custnm}, '%')
order by a.quatym desc, a.quatno desc, b.qrowno asc

